const updateInvestor = `-- name: UpdateInvestor :exec
UPDATE investors
SET user_id = $1, name = $2, email = $3,
    phone = $4, join_date = $5::text::date,
    status = $6, notes = $7, updated_at = now()
WHERE id = $8
`

type UpdateInvestorParams struct {
	UserID   *uuid.UUID `json:"user_id"`
	Name     string     `json:"name"`
	Email    *string    `json:"email"`
	Phone    *string    `json:"phone"`
	JoinDate string     `json:"join_date"`
	Status   string     `json:"status"`
	Notes    string     `json:"notes"`
	ID       uuid.UUID  `json:"id"`
}

func (q *Queries) UpdateInvestor(ctx context.Context, arg UpdateInvestorParams) error {
	_, err := q.db.Exec(ctx, updateInvestor,
		arg.UserID,
		arg.Name,
		arg.Email,
		arg.Phone,
		arg.JoinDate,
		arg.Status,
		arg.Notes,
		arg.ID,
	)
	return err
}

const updateProfitSettings = `-- name: UpdateProfitSettings :exec
UPDATE profit_settings
SET reserve_percent = $1::text::numeric,
    updated_by = $2, updated_at = now()
WHERE id = 1
`

